INSERT INTO `workspace_states` (`id`, `payload`, `updated_by`, `updated_at`)
VALUES ('default', '{"schemaVersion":2,"hotspots":[{"id":2026073001,"rank":1,"source":"Ethan Mollick","sourceUrl":"https://x.com/emollick/status/2082616135170555984","sourceType":"X","age":"2小时前","title":"同一个 AI，为什么别人用得像员工，你用得像搜索框？","summary":"模型没有突然变聪明，真正拉开效果的可能是使用方式：能不能持续推进任务、保留中间结果，并在失败后继续调整。","heat":84,"scarcity":55,"fit":94,"reason":"原帖在采集时已有2.09万浏览和255赞。它能被改写成普通人马上能理解的AI使用误区，而不是继续介绍抽象模型参数。","angle":"别急着换模型，先把一次问答改成连续协作","platforms":["小红书","抖音","视频号"],"category":"AI 技巧","status":"待审核","selected":true,"assignee":"待分配","live":true,"sourceCapturedAt":"2026-07-30T10:38:36+08:00","evidenceConfidence":82,"domesticCoverage":"尚未完成小红书、抖音同角度语义检索，国内稀缺度按规则封顶55；发布前需搜索“AI 连续任务、上下文、换模型”等核心表达。","humanCheck":"需要核对引用的ARC-AGI-3结果及设置变化，不能把一次基准结果写成所有任务都有效。","evidenceId":"x-2082616135170555984","engagement":{"views":20936,"likes":255,"replies":23,"reposts":13,"bookmarks":56},"engagementLabel":"20,936 浏览 · 255 赞 · 23 回复 · 13 转发 · 56 收藏","discussionUrl":"https://x.com/emollick/status/2082616135170555984","discussionFocus":["当前已核验原帖正文和互动总数，评论样本尚未逐条采集。","原帖核心判断是：模型能力之外，连续运行、上下文管理和任务外壳也会显著影响结果。","引用帖认为跨多个上下文窗口工作和压缩机制影响了基准结果，但仍需核验原实验。"],"reuseIdeas":["用“搜索框”和“员工”的对比解释一次问答与连续协作，不讲工程术语。","给一个真实场景：先让AI问清需求，再做初稿、检查遗漏、根据反馈重写。","保留原帖观点出处，不把引用中的基准成绩改写成自己的实测。"],"localizedTranslation":"模型只是其中一部分，外层的运行机制同样重要。我们对怎样设计这套机制的理解才刚刚开始。即使模型本身不变，仍有大量潜力没有被挖出来。","analysisState":"已分析"},{"id":2026073002,"rank":2,"source":"Allie K. Miller","sourceUrl":"https://www.instagram.com/alliekmiller/p/DbWUys9j_Jm/","sourceType":"Instagram","age":"1天前","title":"你发出去的 AI 分享链接，可能比你想象中公开","summary":"Allie K. Miller 提醒用户检查AI对话和云盘中的“知道链接即可访问”内容。这个题不该只做风险新闻，更适合变成一份马上能照着做的隐私自查。","heat":88,"scarcity":55,"fit":96,"reason":"采集时公开795赞、134评论、32转发。题目和每个使用AI、网盘的人有关，实际帮助比单纯转述隐私新闻更强。","angle":"现在花3分钟，检查你公开过的AI对话和云盘链接","platforms":["小红书","抖音","视频号"],"category":"AI 技巧","status":"待审核","selected":true,"assignee":"待分配","live":true,"sourceCapturedAt":"2026-07-30T10:38:36+08:00","evidenceConfidence":78,"domesticCoverage":"尚未完成国内平台同题搜索，稀缺度封顶55。发布前需搜索“AI分享链接被搜索、Claude公开链接、网盘任何人可查看”等说法。","humanCheck":"必须核验Anthropic当前的公开分享与搜索索引机制；不要展示或复述任何家庭投资、医疗排班等敏感原始内容。","evidenceId":"instagram-DbWUys9j_Jm","engagement":{"likes":795,"comments":134,"reposts":32},"engagementLabel":"795 赞 · 134 评论 · 32 转发 · 浏览量和收藏未公开","discussionUrl":"https://www.instagram.com/alliekmiller/p/DbWUys9j_Jm/","discussionFocus":["可见评论中大量“JOB”是响应作者领取资料的口令，不能当成用户赞同隐私结论的证据。","目前可核验的非口令评论样本很少，没有足够证据概括评论区共识。","正文真正有价值的部分是提醒用户检查“知道链接即可访问”的历史内容。"],"reuseIdeas":["不搬运敏感案例，直接给AI分享链接、云盘权限和历史公开页面的自查入口。","标题强调“检查”，不使用“你的隐私已经泄露”这种无法证明的恐吓。","做成手机录屏式短视频，边操作边解释哪些内容不应该公开。"],"localizedTranslation":"作者称她在可被索引的Anthropic公开内容中看到了由创建者自行分享的敏感材料，包括家庭投资策略和医疗机构的排班。她建议大家检查AI对话和云盘里仍设置为“知道链接即可访问”的内容。","analysisState":"已分析"},{"id":2026073003,"rank":3,"source":"Ethan Mollick","sourceUrl":"https://x.com/emollick/status/2082502289898508640","sourceType":"X","age":"10小时前","title":"公司上 AI 后，先裁人还是先把业务做大？","summary":"AI会改变工作，但企业可以选择把它当裁员工具，也可以先让现有员工完成过去做不到的业务。原帖是观点，不是统计结论。","heat":81,"scarcity":55,"fit":91,"reason":"采集时有1.62万浏览、198赞、31回复和94收藏。它把抽象的“AI改变工作”变成老板和员工都能参与的现实选择。","angle":"最偷懒的AI战略，是只算能少招几个人","platforms":["小红书","抖音","公众号"],"category":"个人 IP","status":"待审核","selected":true,"assignee":"待分配","live":true,"sourceCapturedAt":"2026-07-30T10:38:36+08:00","evidenceConfidence":85,"domesticCoverage":"国内已有大量“AI替代岗位”内容，但尚未核验“裁员还是扩张业务”这个具体角度的覆盖程度，稀缺度封顶55。","humanCheck":"这是作者观点，不能包装成企业调研结论；如果加入公司案例，需另外寻找公开证据。","evidenceId":"x-2082502289898508640","engagement":{"views":16204,"likes":198,"replies":31,"reposts":27,"bookmarks":94},"engagementLabel":"16,204 浏览 · 198 赞 · 31 回复 · 27 转发 · 94 收藏","discussionUrl":"https://x.com/emollick/status/2082502289898508640","discussionFocus":["当前已核验正文与互动总数，评论样本尚未逐条采集。","原帖把企业采用AI分成两种思路：削减人数，或扩大员工能承担的工作。","原帖没有给出普遍适用的数据结论，讨论应保持为管理观点。"],"reuseIdeas":["从老板最容易做的成本题切入，再转到AI能否创造新收入。","让读者用一个问题判断公司方向：AI省下来的时间，最后变成裁员指标还是新业务？","可以加入自有项目或客户案例，但必须清楚区分事实和个人判断。"],"localizedTranslation":"AI必然会改变工作，但工作究竟怎么变并不是注定的。缺乏想象力的公司会把AI当成裁员机会；有远见的公司会用AI扩大人的职责，让工作做得更好。","analysisState":"已分析"}],"drafts":[{"id":3026073001,"hotspotId":2026073001,"platform":"小红书","title":"同一个AI，为啥别人用得像员工，你用得像搜索框？","body":"同一个AI，为什么有人能拿它做完一整件事，有人问两句就觉得“不好用”？\n\n差别经常不在模型，而在你有没有让它继续干下去。\n\n很多人的用法是：丢一句问题，等一个答案，不满意就关掉。这样用，再强的模型也只是一个会说话的搜索框。\n\n我现在更习惯先把场景和结果告诉它，让它反过来问我缺什么。初稿出来后不急着复制，而是继续让它找漏洞、核对要求、按反馈重做。中间的决定也留在同一个任务里，不要每一步都重新开聊。\n\nEthan Mollick 刚发了一条相关讨论。采集时这条有2万多浏览。他的核心判断很简单：模型能力只是一半，让AI怎样持续工作的那套方法，可能还有大量潜力没被用出来。\n\n所以如果你最近觉得AI效果一般，先别急着再买一个工具。拿一件真实工作试试：让它从“回答问题”变成“把事情推进到交付”。\n\n你现在最常让AI做的是一次问答，还是完整任务？","visual":"4:5黑白手绘信息卡。左侧是一次性搜索框，右侧是会追问、初稿、检查、修改的任务路径。只保留标题和四个短词，不展示未经核验的模型成绩。","videoScript":"同一个AI，为什么别人用得像员工，你用得像搜索框？问题可能不是模型，而是你每次只让它回答一句。下一次别直接要答案，先告诉它你要交付什么，让它追问缺的信息。初稿出来后，再让它检查遗漏、按你的反馈重做，而且别中途换一个新聊天。Ethan Mollick刚发了一条相关讨论：模型之外，让AI怎样持续工作的机制还有很多潜力。先别急着换工具，拿一件真实工作，把AI从回答问题用到完成任务。","version":"V1 · Codex本地化初稿","updatedBy":"Codex AI Content Operator","status":"待审核","reviewNote":""},{"id":3026073002,"hotspotId":2026073002,"platform":"小红书","title":"现在去检查一下，你发过的AI分享链接","body":"现在去翻一下你发过的AI分享链接。\n\n不是让你恐慌，是很多人真的会忘记：当时为了给同事或朋友看，随手点了“知道链接的人可查看”，事情结束以后却没有关掉。\n\nAllie K. Miller 昨天发了一组提醒。她说自己在可被索引的公开内容里看到了非常敏感的材料。采集时原帖有795赞、134条评论和32次转发。\n\n这件事最有用的部分不是围观别人的隐私，而是马上检查自己的：\n\n打开你用过的AI产品，看看历史分享链接还在不在；再去云盘检查“任何人可查看”的文件；客户资料、身份证明、合同、排班、财务内容，只要已经不需要分享，就收回权限。\n\n注意，这不等于所有分享链接都会被搜索到，也不代表你的内容已经泄露。具体公开范围要看产品当前的设置。我们能确定的是：长期开放、自己又忘记的链接，本来就不该留着。\n\n我刚刚也顺手查了一遍。你上一次清理公开链接是什么时候？","visual":"4:5黑白简笔画自查卡：AI分享链接、云盘权限、历史公开页三个勾选框。避免出现真实敏感材料截图，页脚注明“不同产品设置不同，以当前权限页为准”。","videoScript":"现在花三分钟，检查你以前发过的AI分享链接。很多人为了给同事看，点过“知道链接的人可查看”，用完以后却忘了关。Allie K. Miller昨天发帖提醒这类公开内容可能包含非常敏感的材料。别去围观案例，直接检查自己：AI产品里的历史分享链接、云盘里任何人可查看的文件，还有客户、合同、财务相关内容。注意，不是说你的内容一定泄露了，具体要看产品设置。但已经不用的公开链接，现在就收回来。","version":"V1 · Codex本地化初稿","updatedBy":"Codex AI Content Operator","status":"待审核","reviewNote":""},{"id":3026073003,"hotspotId":2026073003,"platform":"小红书","title":"最偷懒的AI战略，是只算能少招几个人","body":"AI进公司以后，最偷懒的做法就是先算：能少招几个人？\n\n这个账很好算。一个人用了AI以后快了30%，看起来就能少配一点人。但省出来的时间如果只是变成更高的工作量，最后得到的往往不是创新，而是一群更累、也更想走的人。\n\nEthan Mollick 今天提了另一个思路：AI一定会改变工作，但公司可以选择怎么变。有人把它当裁员工具，也有人让原来的人去做以前顾不过来的客户、产品和新业务。\n\n我觉得真正该问的不是“AI能替掉谁”，而是：同样这批人，有了AI以后，能不能多服务一种客户，多卖一种产品，或者把以前嫌麻烦、不赚钱的环节做起来？\n\n当然，这是一种管理观点，不是已经被证明的企业统计结论。但它比“用了AI就裁员”多走了一步。\n\n如果你是老板，AI省下来的时间会进入裁员表，还是新业务表？","visual":"4:5黑白手绘天平：左边“少招人”，右边“多做新业务”。画面只放一个问题，不使用夸张增长数字。","videoScript":"AI进公司以后，最偷懒的做法就是先算能少招几个人。这个账很好算，但Ethan Mollick今天提了另一条路：AI一定会改变工作，怎么变却不是注定的。公司可以拿它裁人，也可以让同一批员工去做过去顾不过来的客户、产品和新业务。所以下次别只问AI能替掉谁，问问同样这批人有了AI以后，能不能多创造一种收入。当然这是一种管理观点，不是统计结论。你会把AI省下来的时间放进裁员表，还是新业务表？","version":"V1 · Codex本地化初稿","updatedBy":"Codex AI Content Operator","status":"待审核","reviewNote":""}],"discoveryMeta":{"runId":"browser-social-2026-07-30-01","capturedAt":"2026-07-30T10:38:36+08:00","coverageLabel":"3条真实社媒内容已核验，候选池持续补充","gapCount":2,"editorialBrief":"不设20条展示门槛。真实合格内容先进入工作台；优先高互动、好理解、有实际用处的AI技巧和观点。"}}', 'Codex AI Content Operator', '2026-07-30T10:38:36+08:00')
ON CONFLICT (`id`) DO UPDATE SET
